3	import { Auth, Principal, Public } from './auth';
4	import { UsersService } from '../users/users.service';
5	import { Db } from '../db/db';
6	import { streamToken } from './stream-token';
7	
8	class VerifyTokenDto {
9	  /** Firebase App Check / device fingerprint — second layer against multi-accounting. */
10	  @IsOptional() @IsString() @MaxLength(128) deviceId?: string;
11	}
12	
13	@Controller('auth')
14	export class AuthController {
15	  constructor(
16	    private readonly users: UsersService,
17	    private readonly db: Db,
18	  ) {}
19	
20	  /**
21	   * Exchanges a verified Firebase ID token for an app session (i.e. a users row).
22	   * Idempotent — the client calls it on every cold start.
23	   */
24	  @Post('verify-token')
25	  async verifyToken(@Auth() principal: Principal, @Body() dto: VerifyTokenDto) {
26	    const user = await this.users.provision(principal, dto.deviceId);
27	    return {
28	      user,
29	      onboarding: {
30	        profileComplete: Boolean(user.gender),
31	        verificationRequired: true,
32	      },
33	    };
34	  }
35	
