151	  // ─── shared error wrapper ───────────────────────────────────────────────
152	  Future<void> _run(Future<void> Function() fn) async {
153	    setState(() { _busy = true; _error = null; });
154	    try {
155	      await fn();
156	    } on FirebaseAuthException catch (e) {
157	      if (mounted) setState(() => _error = _label(e));
158	    } catch (e, st) {
159	      // Log full error for debugging
160	      debugPrint('[Auth] Error: $e\n$st');
161	      if (mounted) setState(() => _error = _generic(e));
162	    } finally {
163	      if (mounted) setState(() => _busy = false);
164	    }
165	  }
166	
167	  static String _label(FirebaseAuthException e) => switch (e.code) {
168	        'invalid-email' => 'That email address is not valid.',
169	        'user-disabled' => 'This account has been disabled.',
170	        'user-not-found' => 'No account found — try creating one.',
171	        'wrong-password' => 'Incorrect password.',
172	        'email-already-in-use' => 'An account already exists for that email.',
173	        'weak-password' => 'Choose a stronger password (8+ characters).',
174	        'invalid-verification-code' => 'That code is incorrect.',
175	        'invalid-phone-number' => 'Enter a valid phone number with the country code.',
176	        'too-many-requests' => 'Too many attempts — please wait a few minutes.',
177	        'network-request-failed' => 'No internet connection.',
178	        'missing-verification-id' => 'Verification session expired. Request a new code.',
179	        'session-expired' => 'Verification session expired. Request a new code.',
180	        'quota-exceeded' => 'SMS quota exceeded. Try again later.',
181	        'captcha-check-failed' => 'reCAPTCHA verification failed. Try again.',
182	        _ => e.message ?? 'Something went wrong.',
183	      };
184	
185	  static String _generic(Object e) {
186	    final s = e.toString();
187	    if (s.contains('network') || s.contains('SocketException')) {
188	      return 'No internet connection.';
189	    }
190	    if (s.contains('not configured') || s.contains('PlatformException')) {
191	      return 'Auth service not configured for this environment.';
192	    }
193	    if (s.contains('recaptcha') || s.contains('RECAPTCHA')) {
194	      return 'Security check failed. Please try again.';
195	    }
196	    return 'Sign-in failed — please try again.';
197	  }
