199	  // ─── Google Sign-In ─────────────────────────────────────────────────────
200	  Future<void> _signInWithGoogle() => _run(() async {
201	        if (kIsWeb) {
202	          await _auth.signInWithPopup(GoogleAuthProvider());
203	          return;
204	        }
205	        final googleUser = await GoogleSignIn().signIn();
206	        if (googleUser == null) return; // user cancelled
207	        final ga = await googleUser.authentication;
208	        final credential = GoogleAuthProvider.credential(
209	          idToken: ga.idToken,
210	          accessToken: ga.accessToken,
211	        );
212	        await _auth.signInWithCredential(credential);
213	      });
214	
215	  // ─── Email auth ─────────────────────────────────────────────────────────
216	  Future<void> _emailAuth({required bool create}) => _run(() async {
217	        final email = _emailCtrl.text.trim();
218	        final pass = _passwordCtrl.text;
219	        if (email.isEmpty || pass.isEmpty) throw Exception('Please fill in email and password.');
220	        if (create) {
221	          await _auth.createUserWithEmailAndPassword(email: email, password: pass);
222	        } else {
223	          await _auth.signInWithEmailAndPassword(email: email, password: pass);
224	        }
225	      });
226	
227	  // ─── Phone: send OTP ────────────────────────────────────────────────────
228	  Future<void> _sendOtp() => _run(() async {
229	        final raw = _phoneCtrl.text.trim().replaceAll(RegExp(r'\s+'), '');
230	        if (raw.isEmpty) throw Exception('Enter a phone number first.');
231	        final full = '${_country.dialCode}$raw';
232	
233	        // Validate phone number format (basic E.164 check)
234	        if (!RegExp(r'^\+[1-9]\d{7,14}$').hasMatch(full)) {
235	          throw Exception('Invalid phone number format. Include country code.');
236	        }
237	
238	        await _auth.verifyPhoneNumber(
239	          phoneNumber: full,
240	          forceResendingToken: _resendToken,
241	          verificationCompleted: (cred) async {
242	            // Auto-verification on Android
243	            try {
244	              await _auth.signInWithCredential(cred);
245	            } catch (_) {
246	              // Ignore auto-verification failures
247	            }
248	          },
249	          verificationFailed: (e) {
250	            if (mounted) {
251	              setState(() => _error = _label(e));
252	            }
253	          },
254	          codeSent: (id, resend) {
255	            if (mounted) {
256	              setState(() {
257	                _verificationId = id;
258	                _resendToken = resend;
259	                _codeSent = true;
260	                _error = null;
261	              });
262	            }
263	          },
264	          codeAutoRetrievalTimeout: (_) {},
265	          timeout: const Duration(seconds: 120), // Increased from 60s
266	        );
267	      });
268	
269	  // ─── Phone: confirm OTP ──────────────────────────────────────────────────
270	  Future<void> _confirmOtp() => _run(() async {
271	        final id = _verificationId;
272	        final code = _otpCtrl.text.trim();
273	        if (id == null || code.isEmpty) throw Exception('Enter the 6-digit code sent to your phone.');
274	        if (code.length != 6) throw Exception('Code must be 6 digits.');
275	        final cred = PhoneAuthProvider.credential(verificationId: id, smsCode: code);
276	        await _auth.signInWithCredential(cred);
277	      });
278	
279	  // ─── Resend ──────────────────────────────────────────────────────────────
280	  void _resetPhone() => setState(() {
281	        _codeSent = false;
282	        _verificationId = null;
283	        _otpCtrl.clear();
284	        _error = null;
285	      });
