486	class _GoogleGPainter extends CustomPainter {
487	  @override
488	  void paint(Canvas canvas, Size size) {
489	    const colors = [Color(0xFF4285F4), Color(0xFF34A853), Color(0xFFFBBC05), Color(0xFFEA4335)];
490	    final center = Offset(size.width / 2, size.height / 2);
491	    final r = size.width / 2;
492	    final sweep = (2 * 3.14159265) / 4;
493	    final paint = Paint()..style = PaintingStyle.stroke..strokeWidth = size.width * 0.28;
494	    for (int i = 0; i < 4; i++) {
495	      paint.color = colors[i];
496	      canvas.drawArc(Rect.fromCircle(center: center, radius: r * 0.7),
497	          -3.14159265 / 2 + i * sweep, sweep - 0.08, false, paint);
498	    }
499	    // horizontal bar
500	    paint
501	      ..color = Color(0xFF4285F4)
502	      ..strokeWidth = size.width * 0.28;
503	    canvas.drawLine(
504	      Offset(center.dx, center.dy),
505	      Offset(size.width, center.dy),
506	      paint,
507	    );
508	  }
509	
510	  @override
511	  bool shouldRepaint(covariant CustomPainter old) => false;
512	}
