          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Icon(Icons.error_outline, color: _pink, size: 18),
            const SizedBox(width: 8),
            Expanded(
              child: Semantics(
                liveRegion: true,
                child: Text(message, style: const TextStyle(color: _pinkDeep, fontSize: 13)),
              ),
